import{routeQuestion,validatePlan,PLANS}from'./intent-router.js';import{createContext,runTool,TOOL_LABELS}from'./tool-registry.js';import{fmt}from'../analytics/stats.js';import{confidence,RULES}from'../analytics/config.js';
const TITLES={GENERAL_SUMMARY:'Your club at a glance',ATTENDANCE_DECLINE:'What may be behind the attendance change',ATTENDANCE_TREND:'How attendance is changing',RETENTION:'Who comes back',PROMOTION_EFFECTIVENESS:'What promotion data can tell us',MEETING_TYPE_COMPARISON:'Which meeting formats stand out',FORECAST:'An estimate for your next meeting',NEXT_MEETING_STRATEGY:'A plan to test next',ANOMALY_EXPLANATION:'What stood out in your meetings',DATA_QUALITY:'How ready is your data?',UNSUPPORTED:'Let’s ask a club-performance question'};
export class ClubPulseAnalyst{
constructor({planner=null,timeoutMs=1800}={}){this.planner=planner;this.timeoutMs=timeoutMs}
async analyze(question,rows,{quality=null,event=null,onTool=()=>{}}={}){let plan=routeQuestion(question),mode='Local evidence-based analysis',providerWarning=null;const ctx=createContext(rows,quality);
// Optional future server-backed planner receives only aggregate metadata. Its response
// may select an allowlisted intent, never prose, calculations, tool code, or member IDs.
if(this.planner&&plan.intent!=='UNSUPPORTED'){let timer;try{plan=validatePlan(await Promise.race([this.planner.plan(question,{summary:runTool('summarize_dataset',ctx),allowedIntents:Object.keys(PLANS)}),new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('Planner unavailable')),this.timeoutMs)})]));mode='Assisted routing · calculated evidence'}catch{providerWarning='AI routing was unavailable. Local analysis completed instead.'}finally{clearTimeout(timer)}}
const names=[...new Set(['validate_dataset','summarize_dataset',...PLANS[plan.intent]])],outputs={},trace=[];for(const name of names){try{const params=['calculate_attendance_trend','compare_recent_period'].includes(name)?{period:plan.period}:name==='forecast_attendance'?{event}:{};outputs[name]=runTool(name,ctx,params);trace.push({tool:name,label:TOOL_LABELS[name],status:outputs[name].available===false?'limited':'complete',sampleSize:outputs[name].sampleSize??ctx.rows.length});await onTool(trace.at(-1))}catch{trace.push({tool:name,label:TOOL_LABELS[name],status:'unavailable',sampleSize:0});outputs[name]={available:false,warnings:['This analysis could not be completed. Other results remain available.']}}}
return synthesize(question,plan,outputs,trace,mode,providerWarning)}
}
export function synthesize(question,plan,o,trace,mode,providerWarning=null){const n=o.summarize_dataset?.sampleSize??0,signals=[],caveats=[];const add=(title,text,source)=>signals.push({title,text,source});let summary=n?`Analysis of ${n} recorded meetings.`:'Add meeting data or open the demo to begin.';const trend=o.calculate_attendance_trend??o.compare_recent_period;
if(plan.intent==='UNSUPPORTED'){summary='I can analyze attendance, meeting formats, promotion, retention, forecasts, and data quality. Try “What changed recently?”';return{question,title:TITLES[plan.intent],summary,signals:[],recommendations:[],confidence:confidence(n),caveats:['The local question router supports club-analytics topics; it is not a general-purpose chatbot.'],trace,mode,intent:plan.intent,outputs:o}}
if(trend?.available){summary=trend.percentChange==null?`Average attendance changed from ${fmt(trend.baseline)} to ${fmt(trend.current)} (${trend.label}).`:`Attendance is ${trend.percentChange<0?'down':trend.percentChange>0?'up':'unchanged by'} ${fmt(Math.abs(trend.percentChange))}% (${trend.label}).`;add('Attendance comparison',`Recent average: ${fmt(trend.current)} across ${trend.recentCount} meetings; comparison average: ${fmt(trend.baseline)} across ${trend.previousCount}.`,'calculate_attendance_trend');if(plan.intent==='ATTENDANCE_DECLINE'&&trend.change>=0)caveats.push('Your selected comparison does not show a decline. The question’s premise was not assumed to be true.')}else if(trend)caveats.push(...trend.warnings??[]);
const member=o.analyze_member_engagement;if(member?.trend)add('Returning-member participation',`Returning attendees averaged ${fmt(member.trend.recentCount)} in the last three meetings vs ${fmt(member.trend.previousCount)} previously. Their share changed from ${fmt(member.trend.previous*100)}% to ${fmt(member.trend.recent*100)}%. This is turnout share, not cohort retention.`,'analyze_member_engagement');else if(member?.available)add('Returning attendees',`${fmt(member.returningShare*100)}% of recorded attendance was from returning members across ${member.sampleSize} usable meetings.`,'analyze_member_engagement');
const timingPromotion=o.analyze_promotion_timing;if(timingPromotion?.trend)add('When promotion started',`Promotion began an average of ${fmt(timingPromotion.trend.recent)} days ahead in the last three meetings, compared with ${fmt(timingPromotion.trend.previous)} previously.`,'analyze_promotion_timing');
const recentFormats=o.compare_recent_formats;if(recentFormats)for(const f of recentFormats.counts)add('Recent meeting format',`${f.count} of the last ${recentFormats.sampleSize} meetings used ${f.name}.${f.historical?.count>=3?` Earlier meetings of this format averaged ${fmt(f.historical.average)} attendees across ${f.historical.count} meetings.`:''}`,'compare_recent_formats');
const signup=o.analyze_signup_engagement;if(signup?.available)add('Pre-meeting signups',`Average signups: ${fmt(signup.averageSignups)}. Attendance was ${fmt(signup.attendancePerSignup*100)} per 100 signups across ${signup.sampleSize} meetings. Walk-ins can make this exceed 100%; it is not tracked conversion.`,'analyze_signup_engagement');
const a=o.calculate_attendance_metrics;if(a?.sampleSize)add('Attendance baseline',`Average ${fmt(a.average)}; median ${fmt(a.median)}; ${a.total} total check-ins across ${a.sampleSize} meetings.`,'calculate_attendance_metrics');
const reach=o.analyze_social_reach;if(reach?.available){if(reach.trend)add('Social reach changed',`Last three meetings averaged ${fmt(reach.trend.recent)} accounts reached; the previous three averaged ${fmt(reach.trend.previous)}. These may not be the same periods as a month-based attendance comparison.`,'analyze_social_reach');if(reach.correlation!=null){const r=reach.correlation;add('Reach and attendance',`${Math.abs(r)<.2?'Little linear relationship':`${Math.abs(r)<.5?'A modest':'A stronger'} ${r<0?'negative':'positive'} relationship`} appears in ${reach.sampleSize} complete pairs. This does not show that reach caused turnout.`,'analyze_social_reach')}else caveats.push(...reach.warnings)}else if(reach)caveats.push('Social reach was not included, so its relationship with attendance is unavailable.');
for(const name of ['compare_meeting_types','compare_promotion_channels']){const comp=o[name];if(!comp)continue;if(comp.best)add(name==='compare_meeting_types'?'Meeting format':'Promotion strategy',`${comp.best.name} averaged ${fmt(comp.best.average)} attendees across ${comp.best.count} meetings (${fmt(comp.best.difference)} compared with the club average).` ,name);else caveats.push(comp.available?'No clear category leader: at least two groups need three meetings each, and the dataset needs five meetings.':`${name==='compare_meeting_types'?'Meeting formats':'Promotion methods'} were not included.`)}
const timing=o.compare_timing;for(const[k,label]of[['time','Meeting time'],['weekday','Weekday']])if(timing?.[k]?.best){const g=timing[k].best;add(label,`${g.name} averaged ${fmt(g.average)} attendees across ${g.count} meetings.`, 'compare_timing')}
const ret=o.calculate_retention;if(ret?.available){add('Newcomer return visits',ret.rate==null?'Not enough follow-up meetings to calculate the three-meeting return rate.':`${ret.returned} of ${ret.eligible} eligible newcomers (${fmt(ret.rate*100)}%) returned within their next three meetings.`,'calculate_retention');if(ret.trend&&!member?.trend)add('Returning-attendee share',`Average share was ${fmt(ret.trend.recent*100)}% in the last three meetings vs ${fmt(ret.trend.previous*100)}% in the previous three. This is not cohort retention.`,'calculate_retention')}else if(ret){caveats.push(...ret.warnings);if(ret.aggregate)add('Reported returning turnout',`${fmt(ret.aggregate.returningShare*100)}% returning-attendee share across ${ret.aggregate.sampleSize} meetings; aggregate counts cannot track cohorts.`,'calculate_retention')}
const conv=o.calculate_conversion_rate;if(conv?.available){add('Reach ratios',`${fmt(conv.attendancePerReach*100)} attendance records per 100 accounts reached across ${conv.sampleSize} meetings.${conv.signupsPerReach!=null?` ${fmt(conv.signupsPerReach*100)} signups per 100 reached across ${conv.signupSampleSize} meetings.`:''}`,'calculate_conversion_rate');caveats.push(...conv.warnings)}
const anomalies=o.detect_attendance_anomalies;if(anomalies?.available)add('Unusual turnout',anomalies.items.length?anomalies.items.map(r=>`${r.name}: ${r.attendance} attendees (${r.direction.toLowerCase()})`).join('; '):'No attendance values crossed the robust outlier threshold.','detect_attendance_anomalies');
const forecast=o.forecast_attendance;if(forecast?.available){add('Turnout estimate',`${forecast.result.estimate} attendees; planning range ${forecast.result.low}–${forecast.result.high}. Typical historical error: ${fmt(forecast.report.typicalError)} attendees. ${forecast.result.method}.`,'forecast_attendance');if(forecast.assumedSetup)caveats.push('Forecast uses your most common recorded categories and median reach as an example setup. Use Predict to enter your actual next meeting.');caveats.push('This planning range is an empirical error range, not a calibrated confidence interval.')}else if(forecast)caveats.push(...forecast.warnings??[]);
if(plan.intent==='DATA_QUALITY'){const q=o.validate_dataset;summary=`${q.usableRows} usable meetings from ${q.totalRows} rows.`;add('Data checks',`${q.duplicateRows} duplicate rows; ${q.excludedRows.length} excluded rows; ${q.fieldIssues.length} invalid optional values; ${q.normalizations.length} category normalizations.`,'validate_dataset');caveats.push(...q.warnings)}
if(n<RULES.comparisons)caveats.push(`Only ${n} meetings: basic summaries are available, but there is not enough evidence for reliable forecasts or strong associations.`);if(signals.length&&!['DATA_QUALITY','FORECAST'].includes(plan.intent))caveats.push('These signals can overlap. Observational data cannot establish why attendance changed.');if(providerWarning)caveats.push(providerWarning);
return{question,intent:plan.intent,title:TITLES[plan.intent],summary,signals,recommendations:o.recommend_next_steps?.recommendations??[],confidence:confidence(n,n?Object.values(o.validate_dataset?.missingFields??{}).reduce((s,v)=>s+v,0)/(n*6):1),caveats:[...new Set(caveats)],trace,mode,outputs:o}}
